import{_ as r,C as l,o,c as h,j as d,a as e,E as n,a2 as i}from"./chunks/framework.Decn_Lan.js";const f=JSON.parse('{"title":"AI Infra 实战笔记 · 系列路线图","description":"低成本 AI Infra 实战：沿着 SGLang 的架构一层层拆开推理服务，每篇都附可复现的实测数据和云上花费。","frontmatter":{"title":"AI Infra 实战笔记 · 系列路线图","description":"低成本 AI Infra 实战：沿着 SGLang 的架构一层层拆开推理服务，每篇都附可复现的实测数据和云上花费。"},"headers":[],"relativePath":"blog/ai-infra/index.md","filePath":"blog/ai-infra/index.md","lastUpdated":1795558112000}'),s={name:"blog/ai-infra/index.md"};function c(b,t,p,u,m,y){const a=l("ArchMap");return o(),h("div",null,[t[0]||(t[0]=d("p",{class:"post-eyebrow"},"// series · 中文",-1)),t[1]||(t[1]=d("h1",{id:"系列路线图",tabindex:"-1"},[e("系列路线图 "),d("a",{class:"header-anchor",href:"#系列路线图","aria-label":'Permalink to "系列路线图"'},"​")],-1)),t[2]||(t[2]=d("p",null,[e("本系列以 "),d("strong",null,"SGLang"),e(" 为主线，按它的架构来组织：一个请求从 HTTP 进来，经过调度、显存管理、模型执行，再扩展到多卡和多实例。每一层对应几篇文章，每篇都对准代码里的一个具体组件。")],-1)),t[3]||(t[3]=d("p",null,"编号就是阅读顺序：先跑起来、看清全貌，再沿着请求的路径往下走，最后走出单个实例。",-1)),t[4]||(t[4]=d("ul",null,[d("li",null,"🖥️ 本地：RTX 2070 8GB + WSL2，跑通流程、读源码、调试脚本"),d("li",null,"☁️ 云上：按小时租 GPU，出正式 benchmark。4090 起步，测多卡和 Hopper 特性时才上 A100 / H 系列")],-1)),n(a,{done:[0]}),t[5]||(t[5]=i('<h2 id="为什么从-sglang-开始" tabindex="-1">为什么从 SGLang 开始 <a class="header-anchor" href="#为什么从-sglang-开始" aria-label="Permalink to &quot;为什么从 SGLang 开始&quot;">​</a></h2><ul><li>RadixAttention、调度器、结构化输出、投机解码、PD 分离、Router 都在同一个代码库里，一条主线能从头讲到尾</li><li>代码以 Python 为主，调度逻辑集中在 Scheduler 里，读得动，「原理浅析」可以直接贴源码</li><li>微调也接得上：verl 等 RL 框架用 SGLang 做 rollout 引擎，最后做 GRPO 时，前面的调优经验能直接用</li></ul><p>vLLM 不单独开线，放在「生态与对比」里。等读者理解了 SGLang 的每一层，再做同条件横评。</p><h2 id="贯穿全系列的约定" tabindex="-1">贯穿全系列的约定 <a class="header-anchor" href="#贯穿全系列的约定" aria-label="Permalink to &quot;贯穿全系列的约定&quot;">​</a></h2><ul><li>性能文章一律用 <code>python -m sglang.bench_serving</code>，数据集固定为 <code>random</code>、<code>sharegpt</code>、<code>generated-shared-prefix</code> 三种，参数写进文章，后文好对比</li><li>模型档位固定：本地用 1.5B 级 FP16 小模型，云上用 8B 级稠密模型，MoE 文章换 30B-A3B 级</li><li>每篇在 EnvCard 里写 SGLang 版本和 commit，不同版本的结论不混用</li><li>2070 的硬限制照实写：Turing（sm75）不支持 BF16、FP8、FA3，部分量化 kernel 要求 sm80+。本地跑不了的特性写明原因，再到云上补测</li></ul><h2 id="layer-pre" tabindex="-1">前置：跑起来，看清全貌 <a class="header-anchor" href="#layer-pre" aria-label="Permalink to &quot;前置：跑起来，看清全貌 {#layer-pre}&quot;">​</a></h2><p>先把环境搭好、模型跑起来、学会怎么量，再用一篇把整个架构过一遍，后面每一篇都会回到这张图上。</p><table tabindex="0"><thead><tr><th>#</th><th>主题</th><th>环境</th><th>状态</th></tr></thead><tbody><tr><td>0</td><td><a href="./00-wsl2-sglang-env">从零开始：在 8GB 显卡上搭环境、跑模型、做压测</a>（WSL2 + Docker、Turing 上的 <code>--dtype half</code>、bench_serving 与 TTFT / TPOT / ITL）</td><td>🖥️ 本地</td><td>草稿</td></tr><tr><td>1</td><td>架构总览：一个请求经过哪些进程（TokenizerManager → Scheduler → ModelRunner → Detokenizer），各层之间怎么传数据</td><td>🖥️ 本地</td><td>计划中</td></tr></tbody></table><h2 id="layer-scheduler" tabindex="-1">调度层：Scheduler <a class="header-anchor" href="#layer-scheduler" aria-label="Permalink to &quot;调度层：Scheduler {#layer-scheduler}&quot;">​</a></h2><p>决定每一步哪些请求进 batch、做 prefill 还是 decode。吞吐和延迟的取舍大多在这里。</p><table tabindex="0"><thead><tr><th>#</th><th>主题</th><th>环境</th><th>状态</th></tr></thead><tbody><tr><td>2</td><td>调度循环：continuous batching、chunked prefill 与调度策略（lpm / fcfs）</td><td>☁️ 云上</td><td>计划中</td></tr><tr><td>3</td><td>CPU 开销与 overlap scheduler：GPU 为什么会等 CPU</td><td>🖥️ 本地 + ☁️ 云上</td><td>计划中</td></tr><tr><td>4</td><td>结构化输出：grammar backend 怎么接进调度和采样，xgrammar 的开销有多大</td><td>🖥️ 本地</td><td>计划中</td></tr></tbody></table><h2 id="layer-memory" tabindex="-1">显存与 KV 缓存层 <a class="header-anchor" href="#layer-memory" aria-label="Permalink to &quot;显存与 KV 缓存层 {#layer-memory}&quot;">​</a></h2><p>KV Cache 怎么分配、怎么复用、放不下时去哪。决定了能同时服务多少请求。</p><table tabindex="0"><thead><tr><th>#</th><th>主题</th><th>环境</th><th>状态</th></tr></thead><tbody><tr><td>5</td><td>显存账本：权重、KV Cache 内存池、CUDA Graph 各占多少，<code>--mem-fraction-static</code> 到底在切什么</td><td>🖥️ 本地</td><td>计划中</td></tr><tr><td>6</td><td>RadixAttention：多轮对话、共享 system prompt、few-shot 下的前缀命中率实测</td><td>☁️ 云上</td><td>计划中</td></tr><tr><td>7</td><td>HiCache：GPU 放不下的 KV Cache 溢出到内存，8GB 显卡上收益有多大</td><td>🖥️ 本地 + ☁️ 云上</td><td>计划中</td></tr></tbody></table><h2 id="layer-exec" tabindex="-1">执行层：ModelRunner <a class="header-anchor" href="#layer-exec" aria-label="Permalink to &quot;执行层：ModelRunner {#layer-exec}&quot;">​</a></h2><p>真正在 GPU 上跑前向的地方：kernel 选择、图捕获、量化、投机解码都在这一层。</p><table tabindex="0"><thead><tr><th>#</th><th>主题</th><th>环境</th><th>状态</th></tr></thead><tbody><tr><td>8</td><td>Attention backend 与 CUDA Graph：FlashInfer / Triton / FA3 的取舍</td><td>🖥️ 本地 + ☁️ 云上</td><td>计划中</td></tr><tr><td>9</td><td>量化：FP8 / AWQ / GPTQ / KV Cache FP8，各自对显卡架构的要求</td><td>🖥️ 本地 + ☁️ 云上</td><td>计划中</td></tr><tr><td>10</td><td>投机解码：EAGLE 系列参数怎么调，接受率随 batch size 怎么变</td><td>☁️ 云上</td><td>计划中</td></tr><tr><td>11</td><td>Multi-LoRA 服务：一个 SGLang 实例挂多个适配器</td><td>🖥️ 本地 + ☁️ 云上</td><td>计划中</td></tr></tbody></table><h2 id="layer-parallel" tabindex="-1">并行层：一个实例跨多卡 <a class="header-anchor" href="#layer-parallel" aria-label="Permalink to &quot;并行层：一个实例跨多卡 {#layer-parallel}&quot;">​</a></h2><p>模型或流量超出单卡时，怎么切分权重、请求和专家。</p><table tabindex="0"><thead><tr><th>#</th><th>主题</th><th>环境</th><th>状态</th></tr></thead><tbody><tr><td>12</td><td>稠密模型多卡：TP 与 DP 的配置与扩展性</td><td>☁️ 云上</td><td>计划中</td></tr><tr><td>13</td><td>MoE 多卡：DP Attention 与 EP</td><td>☁️ 云上</td><td>计划中</td></tr></tbody></table><h2 id="layer-cluster" tabindex="-1">集群与运维层：走出单个实例 <a class="header-anchor" href="#layer-cluster" aria-label="Permalink to &quot;集群与运维层：走出单个实例 {#layer-cluster}&quot;">​</a></h2><p>多个实例怎么分流量、拆阶段、上 K8s，以及怎么看清线上在发生什么。</p><table tabindex="0"><thead><tr><th>#</th><th>主题</th><th>环境</th><th>状态</th></tr></thead><tbody><tr><td>14</td><td>可观测性：<code>--enable-metrics</code> + Prometheus + Grafana 看板</td><td>🖥️ 本地</td><td>计划中</td></tr><tr><td>15</td><td>多副本与 Router：cache-aware 负载均衡 vs 轮询</td><td>☁️ 云上</td><td>计划中</td></tr><tr><td>16</td><td>PD 分离：prefill 和 decode 拆到不同实例</td><td>☁️ 云上</td><td>计划中</td></tr><tr><td>17</td><td>K8s 部署 SGLang 与自动扩缩容</td><td>🖥️ 本地 + ☁️ 云上</td><td>计划中</td></tr></tbody></table><h2 id="layer-eco" tabindex="-1">生态与对比 <a class="header-anchor" href="#layer-eco" aria-label="Permalink to &quot;生态与对比 {#layer-eco}&quot;">​</a></h2><p>SGLang 之外：和 vLLM 横评，以及微调、RL 怎么接回 SGLang。</p><table tabindex="0"><thead><tr><th>#</th><th>主题</th><th>环境</th><th>状态</th></tr></thead><tbody><tr><td>18</td><td>SGLang vs vLLM 横评：同模型、同硬件、同压测脚本</td><td>☁️ 云上</td><td>计划中</td></tr><tr><td>19</td><td>LoRA / QLoRA 微调 → SGLang 部署闭环（Unsloth / LLaMA-Factory）</td><td>🖥️ 本地</td><td>计划中</td></tr><tr><td>20</td><td>小规模 GRPO：verl + SGLang rollout</td><td>☁️ 云上</td><td>计划中</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">写作约定</p><p>每篇遵循同一结构：要解决的问题 → 最小可运行示例 → 关键参数 → 实测数据 → 踩坑记录 → 原理浅析，文末附环境版本与云上花费。</p></div>',27))])}const P=r(s,[["render",c]]);export{f as __pageData,P as default};
